package com.jobradar.taxonomy.location;import com.jobradar.taxonomy.common.TaxonomyEntity;import jakarta.persistence.*;@Entity @Table(name="locations")public class LocationEntity extends TaxonomyEntity{@Column(nullable=false,length=100)private String city;@Column(length=100)private String state;@Column(nullable=false,length=100)private String country;protected LocationEntity(){}public LocationEntity(String c,String s,String co){city=c;state=s;country=co;}public String getCity(){return city;}public String getState(){return state;}public String getCountry(){return country;}public void update(String c,String s,String co){city=c;state=s;country=co;}}
